package com.priperi;
import android.content.*;import android.os.SystemClock;import android.view.*;import android.webkit.WebView;import android.widget.*;import androidx.test.core.app.*;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import org.junit.*;import org.junit.runner.RunWith;import java.util.*;import java.util.concurrent.*;import static org.junit.Assert.*;
/** Uses only the local017 fixture and a fake provider page; never reaches Cloudflare. */
@RunWith(AndroidJUnit4.class) public class SignupFlowTest {
 private final Context c=ApplicationProvider.getApplicationContext();private <T>T local(Repository.Job<T> job)throws Exception{CompletableFuture<T> f=new CompletableFuture<>();Repository.local(c,job,f::complete,e->f.completeExceptionally(new AssertionError(e)));return f.get(35,TimeUnit.SECONDS);}
 @Before public void setup()throws Exception{assertTrue(BuildConfig.ALLOW_TEST_DEVICES);assertTrue(BuildConfig.BACKEND_URL.startsWith("http://10.0.2.2:"));c.getSharedPreferences("notification_access",0).edit().putBoolean("asked",true).commit();Repository.reset();local(v->{assertNull(v.account());return true;});}
 @After public void cleanup()throws Exception{InstrumentationRegistry.getInstrumentation().runOnMainSync(()->{for(android.app.Activity a:new ArrayList<>(androidx.test.runner.lifecycle.ActivityLifecycleMonitorRegistry.getInstance().getActivitiesInStage(androidx.test.runner.lifecycle.Stage.RESUMED)))a.finish();});local(v->{if(v.account()!=null)Session.resetAccount(v);Repository.eraseLocal(v);return true;});Repository.reset();}
 @Test public void cancelLeavesNoAccountAndVerifiedMainFrameCanCompleteSignup()throws Exception{
  try(ActivityScenario<MainActivity> screen=ActivityScenario.launch(MainActivity.class)){
   for(int i=0;i<120;i++){boolean[] ready={false};screen.onActivity(a->ready[0]=findHint(a.getWindow().getDecorView(),"Username")!=null);if(ready[0])break;SystemClock.sleep(40);}
   String name="qa_widget_"+UUID.randomUUID().toString().substring(0,8);submit(screen,name);WebView first=awaitWeb();InstrumentationRegistry.getInstrumentation().runOnMainSync(()->{assertFalse(first.getSettings().getAllowFileAccess());assertFalse(first.getSettings().getAllowContentAccess());first.evaluateJavascript("document.getElementById('iframe').click()",null);});SystemClock.sleep(250);assertNull(local(v->v.account()));InstrumentationRegistry.getInstrumentation().sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);SystemClock.sleep(250);assertNull(local(v->v.account()));
   submit(screen,name);WebView second=awaitWeb();InstrumentationRegistry.getInstrumentation().runOnMainSync(()->second.evaluateJavascript("document.getElementById('verify').click()",null));boolean created=false;for(int i=0;i<150;i++){if(local(v->v.account()!=null)){created=true;break;}SystemClock.sleep(40);}if(!created)fail("Verified signup did not finish: "+visibleText(screen));assertEquals(name,local(v->v.account().getString("username")));
  }
 }
 private static String visibleText(ActivityScenario<MainActivity> screen){StringBuilder out=new StringBuilder();screen.onActivity(a->texts(a.getWindow().getDecorView(),out));return out.toString();}
 private static void texts(View v,StringBuilder out){if(v instanceof TextView)out.append(((TextView)v).getText()).append(";");if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)texts(((ViewGroup)v).getChildAt(i),out);}
 private void submit(ActivityScenario<MainActivity> screen,String name){screen.onActivity(a->{findHint(a.getWindow().getDecorView(),"Username").setText(name);findHint(a.getWindow().getDecorView(),"Password").setText("Widget-Password-2026!");findText(a.getWindow().getDecorView(),"Continue").performClick();});}
 private static WebView awaitWeb(){for(int i=0;i<150;i++){WebView[] web={null};InstrumentationRegistry.getInstrumentation().runOnMainSync(()->{try{java.lang.reflect.Field field=GuardedActivity.class.getDeclaredField("privateDialogs");field.setAccessible(true);for(android.app.Activity activity:androidx.test.runner.lifecycle.ActivityLifecycleMonitorRegistry.getInstance().getActivitiesInStage(androidx.test.runner.lifecycle.Stage.RESUMED)){if(!(activity instanceof GuardedActivity))continue;for(Object value:(java.util.Set<?>)field.get(activity)){android.app.Dialog dialog=(android.app.Dialog)value;WebView candidate=findWeb(dialog.getWindow().getDecorView());if(candidate!=null&&candidate.getProgress()==100)web[0]=candidate;}}}catch(Exception error){throw new AssertionError(error);}});if(web[0]!=null){CompletableFuture<Boolean> loaded=new CompletableFuture<>();InstrumentationRegistry.getInstrumentation().runOnMainSync(()->web[0].evaluateJavascript("!!document.getElementById('verify')",value->loaded.complete("true".equals(value))));try{if(loaded.get(2,TimeUnit.SECONDS))return web[0];}catch(Exception ignored){}}SystemClock.sleep(40);}throw new AssertionError("Verification page did not load");}
 private static WebView findWeb(View v){if(v instanceof WebView)return (WebView)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){WebView x=findWeb(((ViewGroup)v).getChildAt(i));if(x!=null)return x;}return null;}
 private static EditText findHint(View v,String hint){if(v instanceof EditText&&hint.contentEquals(((EditText)v).getHint()))return (EditText)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){EditText x=findHint(((ViewGroup)v).getChildAt(i),hint);if(x!=null)return x;}return null;}
 private static View findText(View v,String text){if(v instanceof TextView&&text.contentEquals(((TextView)v).getText()))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View x=findText(((ViewGroup)v).getChildAt(i),text);if(x!=null)return x;}return null;}
}
